<div class="patient-page-heading"><div><span class="eyebrow text-secondary">EQUIPO DE ATENCIÓN</span><h1>Médicos</h1><p class="text-secondary mb-0">Profesionales y especialidades de Clínica Vida Salud.</p></div><a class="btn btn-clinic" href="/medicos/nuevo">+ Registrar médico</a></div>
<section class="patient-card" data-doctor-total="<?= $escape($result['total']) ?>"><div class="patient-list-toolbar"><div><strong><?= $escape($result['total']) ?></strong> médicos encontrados<span class="live-label">Directorio de profesionales</span></div>
<form action="/medicos" method="get" class="medical-search" role="search"><div><label class="visually-hidden" for="q">Buscar médico por nombre, apellido, código o registro</label><input class="form-control" type="search" name="q" id="q" maxlength="200" value="<?= $escape($search) ?>" placeholder="Nombre, código o registro"></div><div><label for="especialidad" class="visually-hidden">Filtrar por especialidad</label><select class="form-select" id="especialidad" name="especialidad"><option value="">Todas las especialidades</option><?php foreach($specialties as $e): ?><option value="<?= $escape($e['id_especialidad']) ?>" <?= $specialty===(int)$e['id_especialidad'] ? 'selected' : '' ?>><?= $escape($e['nombre']) ?><?= $e['estado']==='inactivo' ? ' (inactiva)' : '' ?></option><?php endforeach; ?></select></div><button class="btn btn-clinic" type="submit">Buscar</button><?php if($search!=='' || $specialty!==null): ?><a class="btn btn-outline-secondary" href="/medicos">Limpiar</a><?php endif; ?></form></div>
<?php if(!$result['items']): ?><div class="patient-empty"><h2 class="h5">No hay médicos para mostrar</h2><p class="text-secondary">Prueba con otra búsqueda o especialidad.</p><a href="/medicos">Ver todos los médicos</a></div><?php else: ?><div class="table-responsive"><table class="table patient-table align-middle mb-0"><caption class="visually-hidden">Directorio de médicos</caption><thead><tr><th scope="col">Médico</th><th scope="col">Código / Registro</th><th scope="col">Especialidades</th><th scope="col">Estado</th><th scope="col" class="text-end">Acciones</th></tr></thead><tbody>
<?php foreach($result['items'] as $doctor): ?><tr><td><div class="patient-name"><span class="patient-avatar" aria-hidden="true"><?= $escape(mb_substr($doctor['nombres'],0,1).mb_substr($doctor['apellidos'],0,1)) ?></span><strong><?= $escape($doctor['apellidos'].', '.$doctor['nombres']) ?></strong></div></td><td><?= $escape($doctor['codigo_medico']) ?><small class="d-block text-secondary"><?= $escape($doctor['registro_profesional']) ?></small></td><td class="medical-specialty-cell"><?= $escape($doctor['especialidades'] ?: 'Sin especialidades asociadas') ?></td><td><span class="status-chip <?= $doctor['estado']==='activo' ? 'is-active' : 'is-inactive' ?>"><?= $escape(ucfirst($doctor['estado'])) ?></span></td><td><div class="patient-row-actions"><a href="/medicos/detalle?id=<?= $escape($doctor['id_medico']) ?>" aria-label="Detalle de <?= $escape($doctor['nombres']) ?>">Ver detalle</a><a href="/medicos/editar?id=<?= $escape($doctor['id_medico']) ?>" aria-label="Editar a <?= $escape($doctor['nombres']) ?>">Editar</a></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<div class="patient-pagination"><span><?= $result['total'] ? 'Mostrando '.(($result['page']-1)*10+1).'–'.min($result['total'],$result['page']*10).' de '.$result['total'] : '0 resultados' ?></span><nav aria-label="Páginas de médicos"><ul class="pagination mb-0"><?php $pageUrl=static fn(int $p): string=>'/medicos?'.http_build_query(['q'=>$search,'especialidad'=>$specialty ?? '','pagina'=>$p]); ?>
<?php if($result['page']>1): ?><li class="page-item"><a class="page-link" href="<?= $escape($pageUrl($result['page']-1)) ?>">Anterior</a></li><?php endif; ?>
<?php for($p=max(1,$result['page']-2);$p<=min($result['pages'],$result['page']+2);$p++): ?><li class="page-item <?= $p===$result['page'] ? 'active' : '' ?>"><a class="page-link" href="<?= $escape($pageUrl($p)) ?>" <?= $p===$result['page'] ? 'aria-current="page"' : '' ?>><?= $p ?></a></li><?php endfor; ?>
<?php if($result['page']<$result['pages']): ?><li class="page-item"><a class="page-link" href="<?= $escape($pageUrl($result['page']+1)) ?>">Siguiente</a></li><?php endif; ?></ul></nav></div></section>
